from collections import deque
def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    # find box bounding box of 5s
    pts=[(y,x) for y in range(H) for x in range(W) if g[y][x]==5]
    ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
    top=min(ys); bot=max(ys); left=min(xs); right=max(xs)
    vis=[[False]*W for _ in range(H)]
    q=deque()
    for y in range(top,bot+1):
        for x in range(left,right+1):
            if g[y][x]==0:
                vis[y][x]=True; q.append((y,x))
    while q:
        y,x=q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and not vis[ny][nx]:
                vis[ny][nx]=True; q.append((ny,nx))
    for y in range(top,bot+1):
        for x in range(left,right+1):
            if vis[y][x]: g[y][x]=2
    return g
