def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    import collections
    comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==5 and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; pts=[]
                while st:
                    y,x=st.pop(); pts.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==5 and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                comps.append(pts)
    out=[r[:] for r in g]
    for pts in comps:
        ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
        top=min(ys); bot=max(ys); lo=min(xs); hi=max(xs)
        # interior: rows top..bot, cols lo..hi, currently 0
        for y in range(top,bot+1):
            for x in range(lo,hi+1):
                if g[y][x]==0: out[y][x]=2
