        # nearest vertical edge to loop walls
        dL=lo  # distance from left edge (col 0) to near wall = lo
        dR=W-1-hi
        near = 'L' if dL<=dR else 'R'
        if near=='L':
            for x in range(0,hi):
                if out[brow][x]==0: out[brow][x]=2
        else:
            for x in range(hi+1,W):
                if out[brow][x]==0: out[brow][x]=2
    return out
