def solve(gi):
    g=[r[:] for r in gi]; H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==5 and not seen[i][j]:
                st=[(i,j)]; cells=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            a,b=y+dy,x+dx
                            if 0<=a<H and 0<=b<W and g[a][b]==5 and not seen[a][b]: st.append((a,b))
                comps.append(cells)
    out=[r[:] for r in gi]
    for cells in comps:
        ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
        y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
        interior=[(y,x) for y in range(y0+1,y1) for x in range(x0+1,x1) if g[y][x]==0]
        # nearest vertical edge
        dL=x0; dR=W-1-x1
        side='L' if dL<=dR else 'R'
        if side=='L':
            e=0; o=x1-1
        else:
            e=W-1; o=x0+1
        row=y0-1
        for x in range(e,o+1):
            if out[row][x]==0: out[row][x]=2
        for y,x in interior: out[y][x]=2
    return out
