    g=[r[:] for r in gi]; H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==5 and not seen[i][j]:
                st=[(i,j)]; cells=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            a,b=y+dy,x+dx
                            if 0<=a<H and 0<=b<W and g[a][b]==5 and not seen[a][b]: st.append((a,b))
                comps.append(cells)
    out=[r[:] for r in gi]
    for cells in comps:
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
        dL=x0; dR=W-1-x1
        side='L' if dL<=dR else 'R'
        row=y0-1
        if side=='L':
            for x in range(0,x1):
                if out[row][x]==0: out[row][x]=2
        else:
            for x in range(x0,W):
                if out[row][x]==0: out[row][x]=2
        for y in range(y0+1,y1):
            for x in range(x0+1,x1):
                if out[y][x]==0: out[y][x]=2
    return out
