                st=[(i,j)]; cells=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            a,b=y+dy,x+dx
                            if 0<=a<len(g) and 0<=b<len(g[0]) and g[a][b]==5 and not seen[a][b]: st.append((a,b))
                out.append(cells)
    return out
